import 'package:flutter/material.dart';
// Imports Flutter's tools for building the user interface.

import 'package:firebase_core/firebase_core.dart';
// Imports Firebase Core, which allows our app to connect to Firebase.

import 'firebase_options.dart';
// Imports the Firebase configuration generated by FlutterFire.

// main() is the starting point of every Dart application.
// async allows this function to wait for Firebase to initialize.
Future<void> main() async {
  // Prepares Flutter before we run asynchronous initialization code.
  WidgetsFlutterBinding.ensureInitialized();

  // Connects our Flutter application to our Firebase project.
  // currentPlatform selects the correct settings for the device.
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // Starts the FairShare application after Firebase is initialized.
  runApp(const MyApp());
}

// MyApp is the root widget of our application.
// StatelessWidget means this widget does not manage changing data itself.
class MyApp extends StatelessWidget {
  // Constructor for MyApp.
  // super.key passes the optional widget key to the parent class.
  const MyApp({super.key});

  // build() describes what the application should display.
  @override
  Widget build(BuildContext context) {
    // MaterialApp provides the basic structure and design
    // for a Flutter application using Material Design.
    return MaterialApp(
      // The name of our application.
      title: 'FairShare',

      // Defines the app's colours and visual style.
      theme: ThemeData(
        // Creates a colour scheme based on purple.
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple),

        // Enables Material Design 3 styling.
        useMaterial3: true,
      ),

      // The first screen users see when the app opens.
      home: const Scaffold(
        // Scaffold provides a basic screen layout.
        body: Center(
          // Center places its child in the middle of the screen.
          child: Text('FairShare is connected to Firebase!'),
        ),
      ),
    );
  }
}
